      "content": "{\n  \"schema_version\": \"domainspec.calculation-generation-contract/v1-candidate\",\n  \"selection_version\": \"domainspec.configured-calculations-selection/v1-candidate\",\n  \"protocol_id\": \"typescript.bound-calculation/v1\",\n  \"status\": \"candidate-construction-only\",\n  \"value_profile\": \"domainspec.typescript-exact-uint64/v1\",\n  \"input\": \"Registered checked composition boundary; selected typed-calculation/v1 domain contracts; unchanged canonical calculates edges\",\n  \"representation\": \"Frozen descriptor-bound arrow function; exact separately hashed provider bytes; explicit typed arguments; eager bigint value result\",\n  \"numeric_semantics\": \"UInt64 0..18446744073709551615; bigint, safe integer number or canonical decimal string inputs; safe JSON integer source literals; checked intermediate arithmetic; declared floor, ceil or reject division\",\n  \"failures\": [\"CALCULATION_INPUT\", \"CALCULATION_UNDERFLOW\", \"CALCULATION_OVERFLOW\", \"CALCULATION_DIVIDE_BY_ZERO\", \"CALCULATION_INEXACT\"],\n  \"input_boundary\": \"Exact own enumerable data properties on a plain or null-prototype object; no getter evaluation or value coercion; normalize every declared parameter once, including unused parameters\",\n  \"lowering\": \"Static postorder arithmetic instructions; no runtime AST, expression interpreter, implicit dependency resolution or operation execution\",\n  \"profile_binding\": \"Exact PCR configuration and TypeScript/base profiles; DSR-011 satisfied only by explicitly selected checked boundary, without editing old configuration blockers\",\n  \"authority_effect\": \"none\",\n  \"preservation\": \"No source-schema widening, synthetic Operation, old generator modification, profile admission, public default or CLI integration\",\n  \"claim_ceiling\": \"Candidate-local native behavior and closed generated arithmetic observation for inert inputs and standard intrinsics; not hostile Proxy or modified realm purity\",\n  \"remaining\": [\"standalone source admission DSR-013\", \"full-width authored literals\", \"Python and Rust parity\", \"shared public CLI planning\", \"general composition proof\"]\n}\n",
