      "path": "development/reconciliation-v1/profile-compiler-reconciliation/calculation-v2-contract.json",
      "sha256": "7a666e31e0ce1b19282203cdefb3db7eba78b2a9909792d62a49acc12bfdc383",
      "content": "{\n  \"schema_version\": \"domainspec.calculation-v2-definition/v1-candidate\",\n  \"status\": \"candidate\",\n  \"authority_effect\": \"none\",\n  \"decision_ref\": \"CALCULATION-ADMISSION-DECISION.md\",\n  \"source_version\": \"domainspec.typed-calculation/v2\",\n  \"meaning\": \"A reusable pure arithmetic function over explicitly supplied UInt64 values; it exists independently of any Operation consumer.\",\n  \"input_contract\": {\n    \"parameters\": \"Zero to 128 unique explicit UInt64 inputs; source body inputs exactly match their names and order.\",\n    \"expression\": \"Closed literal, input, add, subtract, multiply and divide nodes; depth at most 32; at most 4096 expression nodes.\",\n    \"literal\": \"Canonical unsigned decimal JSON string in [0, 18446744073709551615]; no JSON number coercion.\",\n    \"rounding\": [\"floor\", \"ceil\", \"reject\"],\n    \"result\": \"UInt64\"\n  },\n  \"runtime_contract\": {\n    \"input\": \"Normalize every explicit input, including unused inputs, from bigint, safe integer number or canonical decimal string.\",\n    \"evaluation\": \"Left then right, once per authored expression occurrence; validate UInt64 bounds at every arithmetic result.\",\n    \"output\": \"Primitive bigint value, no effect envelope.\",\n    \"effects\": \"none\",\n    \"dependencies\": \"explicit inputs only\",\n    \"failures\": [\"CALCULATION_INPUT\", \"CALCULATION_OVERFLOW\", \"CALCULATION_UNDERFLOW\", \"CALCULATION_DIVIDE_BY_ZERO\", \"CALCULATION_INEXACT\"]\n  },\n  \"relationships\": {\n    \"standalone\": \"Zero calculates consumers allowed only for the explicitly authored v2 source.\",\n    \"consumed\": \"Real calculates edges retain existing endpoint, scope and multiplicity rules.\",\n    \"mapping\": \"Computed values are passed explicitly; no Calculation-to-Mapping edge or hidden evaluation.\",\n    \"reads\": \"No implicit repository reads or fabricated supporting Operation.\"\n  },\n  \"compatibility\": \"v1 decoder, literal encoding, required calculates edge and generator remain unchanged; old execution and proof paths reject v2 explicitly; no default migration.\",\n  \"native_form\": \"Descriptor-bound TypeScript arrow function selected explicitly with exact UInt64 realization.\",\n  \"verification\": [\"standalone and real-consumer graphs\", \"legacy rejection\", \"full-width arithmetic\", \"rounding and intermediate failures\", \"hostile inert inputs\", \"independent source observation\", \"compiling semantic mutants\", \"deterministic snapshot-only planning\"]\n}\n",
