      "sha256": "2f11a5a0a33befaf6e074c389f1231d1de3d85abb2690302ac163cbfffb88fde",
      "content": "{\n  \"schema_version\": \"domainspec.composition-boundary-contract/v1-candidate\",\n  \"task_id\": \"DSR-011\",\n  \"selection_version\": \"domainspec.composition-boundary-selection/v1-candidate\",\n  \"status\": \"non-executing-candidate\",\n  \"domain_graph\": \"Only relationships from the checked compiled project graph, retaining kind, endpoints, feature/project scope and exact source evidence. No composition reference or value binding creates a domain relationship.\",\n  \"composition_graph\": \"Source-scoped references from already checked project-composition ontology. Composition identity qualifies every node and reference; calls, maps-from, maps-to and depends-on remain local roles, not DS-D8 verbs.\",\n  \"value_bindings\": \"Preserve checked typed core contracts and declarative-function contracts, including ordered expressions, parameters, explicit call arguments, mapping fields, defaults, nullability and result declarations. This projection introduces no additional argument, type inference, evaluation, lookup or execution.\",\n  \"bridges\": \"Only existing explicit core_bindings may connect a composition-local name to a domain selector. Keep property-name mappings and originating source; never infer bridges from labels or matching ontology text.\",\n  \"coverage\": \"Every domain node, domain relationship, composition node, composition reference, typed core contract, declarative function contract and explicit core binding is represented. Untyped domain nodes remain explicitly listed as not having a typed value contract.\",\n  \"validation_ceiling\": \"The graph is a current in-process checked snapshot. Projection is deterministic and provenance-bound, not an additional proof of type compatibility, canonical admission, dataflow execution, runtime count or generated-code conformance.\",\n  \"compatibility\": \"Original graph, source schemas, relationship authority, composition compiler, Rule/factory selections and defaults remain unchanged. Existing Calculation calculates-edge requirements remain visible and are not repaired by a fabricated Operation.\",\n  \"authority_effect\": \"none\",\n  \"open_questions_ref\": \"../profile-compiler-reconciliation/COMPOSITION-BOUNDARY.md#remaining-work\"\n}\n",
      "size_bytes": 2178
