      "content": "{\n  \"schema_version\": \"domainspec.python-state-machine-semantic-verification/v1-candidate\",\n  \"status\": \"candidate\",\n  \"authority_effect\": \"none\",\n  \"scope\": \"Native State Machine verification in the existing isolated Python project workspace\",\n  \"source_cases\": {\n    \"definition_sha256\": \"da9a3a504fded187bdd6b6956b6695736598f48564c6d85aba396fa9b7688ffb\",\n    \"preparation\": \"Reuse complete language-independent state/trigger matrices, structural fact recipes, guard predictions and malformed-input outcomes without dropping cases\",\n    \"capacity\": \"Retain existing 4096-case bounds; capacity exhaustion leaves the whole row not_evaluable, never a passing prefix\"\n  },\n  \"native_contract\": {\n    \"input\": \"Translate shared string-symbol recipes into generated nominal State/Trigger members only at the verifier boundary; public reducers still reject raw strings, role swaps, foreign enums and forged members\",\n    \"facts\": \"Use inert Python structural carriers without Entity or Value Object factory validation, retaining exact existing UInt64, set, list, optional and sum behavior\",\n    \"outcome\": \"Check exact initial state, transition or rejection, nominal output state, transition identifier, and authored ordered output-intent slots and Event references\",\n    \"integrity\": \"Require frozen callable, descriptor, slot-based results, tuple intents and immutable mappings; replay twice with fresh outcomes and no input mutation or coercion\",\n    \"effects\": \"Audit bounded native reducer replay; intents remain data and are not constructed, published, persisted or dispatched\",\n    \"independent_observation\": \"Reuse whole provider/facade grammar and independent checked-type grammar; bind Event bodies and Rule/runtime dependency bytes; transitive Rules are observed before reducer execution\",\n    \"negative_controls\": \"Three callable binding mutations, native nominal rejections and two compiling whole-source substitutions for every selected State Machine\"\n  },\n  \"execution\": \"One existing bounded isolated semantic process; no new workspace, external dependency, emitter oracle or runtime mode\",\n  \"claim_ceiling\": \"Bounded source conformance only; not arbitrary Python sandboxing, event execution, external effect authorization, full CLI qualification or release\"\n}\n",
