      "content": "{\n  \"schema_version\": \"domainspec.reference-field-factory-contract/v1-candidate\",\n  \"selection_version\": \"domainspec.configured-factories-selection/v7-candidate\",\n  \"language\": \"typescript\",\n  \"component_support_sha256\": \"04125d6abc0e3bb18a624aa0b7390ac4958b0957ea634fdc800ab7135c91c3f9\",\n  \"enum_provider_sha256\": \"378e09358713b431e4a24e664e484feae0122462e47aabfa653ae21a17315fcc\",\n  \"field_contract_sha256\": \"9a012a5a669936620e71a6d8e41457b9ef975dd53703c629c26e000ff1d4262d\",\n  \"bindings\": [\"identity-reference\", \"field-projection\"],\n  \"realization\": \"target-indexed TypeScript field types with type-only imports and deeply frozen literal field binding descriptors; source value validators unchanged\",\n  \"identity_reference\": \"target Entity identity type with the source's existing optional/list/set wrappers; cycles permitted without runtime target imports\",\n  \"field_projection\": \"exact target field type through the existing finite property path; no implicit traversal through optional values, collections or remote references\",\n  \"equality\": \"existing declared value semantics; binding metadata neither brands scalar values by target nor changes Entity identity or Value Object equality\",\n  \"metadata\": \"exact owner, field, kind, target and projection emitted per owner; plan additionally binds target generated path and artifact digest without circular content hashes\",\n  \"validation\": \"all source fields and declared Rules validate as before; binding metadata supplies neither target existence proof nor equality with any live target value\",\n  \"compatibility\": \"versions 1-6 retain closed selections and emitted output; checked field model, helper protocols, profiles and default compiler unchanged\",\n  \"unsupported\": [\"database lookup\", \"referential integrity\", \"automatic field population\", \"remote-reference traversal\", \"nominal scalar reference brands\", \"embedded Entity fields\", \"reference-aware Rule resolution\", \"default integration\", \"profile admission\"],\n  \"authority_effect\": \"none\",\n  \"open_questions_ref\": \"REFERENCE-FIELD-FACTORY-GENERATION.md#open-questions\"\n}\n",
