      "content": "{\n  \"schema_version\": \"domainspec.rule-structured-value-contract/v1-candidate\",\n  \"selection_version\": \"domainspec.configured-rules-selection/v8-candidate\",\n  \"value_profile\": \"domainspec.typescript-exact-uint64/v1\",\n  \"field_contract_sha256\": \"42b57f2517f6c7dcf24492acb76099def9f75926976df47a7b78d559640ea227\",\n  \"inputs\": \"closed data-only facts in the declared scalar, named Entity/Value Object/Enum, optional, list, set and sum types; exact UInt64 inputs normalize to bigint; all formal arguments are required, optional data fields may be absent\",\n  \"named_semantics\": \"checked declarations retain selectors, identity, properties and cardinality; Entity keys use identity while validating all state; Value Object keys use all fields; no construction, invariant execution, provider ownership claim or reference lookup\",\n  \"composition\": \"static specialized normalizers and native typed direct expressions, not a runtime schema or expression interpreter; recursively copied immutable values\",\n  \"equality\": \"typed keys distinguish scalar types, named selectors, absent versus present, sum tags and payloads; list order and occurrences retained; set input duplicates reject after typed normalization\",\n  \"projection\": \"ontology property selectors lower to their checked declared property names; list projection retains occurrences; set projection forms the duplicate-free image under the projected field's equality; no optional traversal or implicit unwrapping\",\n  \"operators\": \"all, any, not, eq, lt over String/UInt64, contains, set_equal, exists, exactly_one, unique with identical-path keys, explicit list to_set and declared rule_ref; checked payload-free Enum variants\",\n  \"compatibility\": \"Rule v1-v7 and factory v1-v11 unchanged; v8 is explicit and old unsupported paths remain rejecting; legacy runtime is not reinterpreted\",\n  \"factory_boundary\": \"explicit successor selection projects normalized owned fields into data-only Rule facts; no raw snapshot reinterpretation, hidden Rule execution or automatic whole-factory parameter binding\",\n  \"authority_effect\": \"none\",\n  \"open_questions_ref\": \"STRUCTURED-RULE-VALUES.md#open-questions\"\n}\n",
